import{_ as l,l as i,o as e,c as s,v as t,p as n,x as o,d as h,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"队头阻塞对照","description":"","frontmatter":{"title":"队头阻塞对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hol-blocking.md","filePath":"cs/hol-blocking.md","lastUpdated":1789023840000}'),d={name:"cs/hol-blocking.md"};function T(H,a,P,_,u,O){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="队头阻塞对照" tabindex="-1">队头阻塞对照 <a class="header-anchor" href="#队头阻塞对照" aria-label="Permalink to &quot;队头阻塞对照&quot;">​</a></h1><div class="epigraph"><p>同名「队头」出现在交换结构、HTTP/1.1 串行响应、以及 TCP 字节流上的 HTTP/2；解法一层一层不同。</p><footer>—— 据 RFC 9112 / 9113；Karol HOL；RFC 9000 对照整理</footer></div><p><a href="/cs/http11-persistent-chunked">HTTP/1.1 持久</a> 把请求排成队。<a href="/cs/http2">HTTP/2 多路</a> 已给应用层解。<a href="/cs/output-queue-hol">交换机 HOL</a> 是结构。<a href="/cs/http11-persistent-chunked">上一课</a> 留下管道化失败。缺口是<strong>对照三层 HOL</strong>，避免混名。本课不把 HTTP/3 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1.1：连接上前一响应未完，后一请求的响应不能开始——应用 HOL。开多连接是笨解，伤 cc。HTTP/2：多流交错，应用 HOL 解了，但 TCP 丢一个段挡住所有流——运输 HOL。QUIC 再解运输。交换机 VOQ 解的是第三种：入端口 FIFO。PFC 暂停是第四种「整口冻」。</p><p>不要用一种队列算法「统一解决」。</p><p><span class="marginnote">教学对照。Kurose 分章讲，这里收口进阶课的词汇。</span></p><h3 id="写-hol-必须加层" tabindex="-1">写 HOL 必须加层 <a class="header-anchor" href="#写-hol-必须加层" aria-label="Permalink to &quot;写 HOL 必须加层&quot;">​</a></h3><p>1.1 应用串行；H2 解之但仍受 TCP；H3 再解运输。交换 VOQ 是第三对象。混名无法排障。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三列对照：层、现象、对策。画三条路径。与 SCTP/QUIC 流对照。</p>',11)),(e(),n(c,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H11%5B%22HTTP%2F1.1%20%E4%B8%B2%E8%A1%8C%22%5D%20--%3E%20H2%5B%22H2%20%E5%A4%9A%E6%B5%81%22%5D%0A%20%20H2%20--%3E%20TCP%5B%22%E4%BB%8D%E5%8F%97%20TCP%20HOL%22%5D%0A%20%20TCP%20--%3E%20H3%5B%22QUIC%20%E5%A4%9A%E6%B5%81%22%5D%0A%20%20SW%5B%22%E8%BE%93%E5%85%A5%20FIFO%22%5D%20--%3E%20VOQ%5B%22VOQ%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TSO 合并不造 1.1 HOL，只改段大小。WFQ 不修 TCP HOL。数据中心 incast 是出口队列，不是 HTTP HOL，但浏览器多连接会加重 incast。CDN 用多连接与 H2 混合。</p><p>命名纪律：写「HOL」必须加层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 HTTP/2 优先级树的全部。HTTP/3 是下一课。后课默认：H2 解应用 HOL，H3 解运输 HOL。</p><p>把所有卡顿都叫 HOL 会无法排障。</p><p>上一课留下的缺口在本课收口；「队头阻塞对照」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/http3">HTTP/3</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>1.1 应用 HOL；H2 解之、TCP 仍堵。</li><li>QUIC 解运输 HOL。</li><li>交换 HOL 是第三对象。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9112/9113/9000；Karol et al.。</li></ul>',10))])}const C=l(d,[["render",T]]);export{m as __pageData,C as default};
